    @State private var selectedBrowseCategory: String? = nil

    private var informationalBrowseCategories: [String] {
        let infEntries = availableEntries.filter { $0.severity == .informational }
        var seen = Set<String>()
        var ordered: [String] = []
        for entry in infEntries {
            if seen.insert(entry.browseCategory).inserted {
                ordered.append(entry.browseCategory)
            }
        }
        // Sort to match the canonical browse category order
        let canonical = SoundCatalog.browseCategories
        return ordered.sorted { (canonical.firstIndex(of: $0) ?? 999) < (canonical.firstIndex(of: $1) ?? 999) }
    }

